    _myspellImpact.push(new RadialFx({ x: p.to.x, y: p.to.y, radius: 0.7, ttl: 0.40 }));
    startShake(cam, 3, 0.14);
    // spawn impact burst particles
    _myspellFx.splice(i, 1);
  }
}
```

