export function effectStrength(world, entityId, effectKey) {
  const key = normalizeKey(effectKey);
  if (!key) return 0;
  const snap = snapshotStatusState(world, entityId);
  if (!snap) return 0;
  return Number(snap.effectStrengths.get(key) || 0);
}

/**
