export function statusStrength(world, entityId, statusType) {
  const key = canonicalStatusType(statusType);
  if (!key) return 0;
  const snap = snapshotStatusState(world, entityId);
  if (!snap) return 0;
  return Number(snap.statusStrengths.get(key) || 0);
